<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { financeApi } from '@/api/business'
import { useAuthStore } from '@/stores/auth'
const auth=useAuthStore(),loading=ref(false),tab=ref('orders'),orders=ref<any[]>([]),prices=ref<any[]>([]),summary=reactive({receivable:0,paid:0,outstanding:0,outstandingOrders:0})
const priceVisible=ref(false),priceEditingId=ref<number|null>(null),orderVisible=ref(false),orderEditingId=ref<number|null>(null),payVisible=ref(false),payOrder=ref<any>()
const price=reactive({itemCode:'',itemName:'',testType:'常规检测',unit:'项',unitPrice:0,unitCost:0,validFrom:new Date().toISOString().slice(0,10),validTo:null as string|null,status:'ENABLED',version:0})
const order=reactive({customerName:'',sampleCount:1,discountAmount:0,remark:'',version:0,items:[{priceItemId:null as number|null,quantity:1}]})
const payment=reactive({amount:0,method:'BANK',referenceNo:'',remark:''})
async function load(){loading.value=true;try{Object.assign(summary,await financeApi.summary());orders.value=await financeApi.orders();prices.value=await financeApi.prices()}finally{loading.value=false}}
function newPrice(){priceEditingId.value=null;Object.assign(price,{itemCode:'',itemName:'',testType:'常规检测',unit:'项',unitPrice:0,unitCost:0,validFrom:new Date().toISOString().slice(0,10),validTo:null,status:'ENABLED',version:0});priceVisible.value=true}
function editPrice(row:any){if(row.referenced){ElMessage.warning('该检测项目已被收费单引用，不能修改');return}priceEditingId.value=row.id;Object.assign(price,{itemCode:row.itemCode,itemName:row.itemName,testType:row.testType,unit:row.unit,unitPrice:Number(row.unitPrice),unitCost:Number(row.unitCost),validFrom:row.validFrom,validTo:row.validTo,status:row.status,version:row.version});priceVisible.value=true}
async function savePrice(){if(priceEditingId.value)await financeApi.updatePrice(priceEditingId.value,price);else await financeApi.createPrice(price);ElMessage.success(priceEditingId.value?'价目已修改':'价目已新增');priceVisible.value=false;await load()}
async function removePrice(row:any){if(row.referenced){ElMessage.warning('该检测项目已被收费单引用，不能删除');return}await ElMessageBox.confirm(`确定删除价目“${row.itemName}”吗？`,'删除价目',{type:'warning'});await financeApi.deletePrice(row.id);ElMessage.success('价目已删除');await load()}
function newOrder(){orderEditingId.value=null;Object.assign(order,{customerName:'',sampleCount:1,discountAmount:0,remark:'',version:0,items:[{priceItemId:null,quantity:1}]});orderVisible.value=true}
async function editOrder(row:any){const items=await financeApi.orderItems(row.id);orderEditingId.value=row.id;Object.assign(order,{customerName:row.customerName,sampleCount:row.sampleCount,discountAmount:Number(row.discountAmount),remark:row.remark||'',version:row.version,items:items.map((x:any)=>({priceItemId:x.priceItemId,quantity:Number(x.quantity)}))});orderVisible.value=true}
async function saveOrder(){if(orderEditingId.value)await financeApi.updateOrder(orderEditingId.value,order);else await financeApi.createOrder(order);ElMessage.success(orderEditingId.value?'收费单已修改':'收费单已创建');orderVisible.value=false;await load()}
async function removeOrder(row:any){await ElMessageBox.confirm(`确定删除收费单“${row.orderNo}”吗？`,'删除收费单',{type:'warning'});await financeApi.deleteOrder(row.id);ElMessage.success('收费单已删除');await load()}
async function returnOrder(row:any){await ElMessageBox.confirm('退回后收费单将恢复为待确认状态，可重新修改，是否继续？','退回收费单',{type:'warning'});await financeApi.returnOrder(row.id);ElMessage.success('收费单已退回待确认');await load()}
async function confirm(row:any){await ElMessageBox.confirm('确认后金额将锁定，是否继续？','确认收费单');await financeApi.confirm(row.id);ElMessage.success('已确认');await load()}
function openPay(row:any){payOrder.value=row;payment.amount=Number(row.receivableAmount)-Number(row.paidAmount);payment.method='BANK';payment.referenceNo='';payment.remark='';payVisible.value=true}
async function savePay(){await financeApi.payment(payOrder.value.id,payment);ElMessage.success('收款登记成功');payVisible.value=false;await load()}
const money=(v:any)=>`¥ ${Number(v||0).toLocaleString('zh-CN',{minimumFractionDigits:2})}`
const orderStatus=(status:string)=>({DRAFT:'待确认',CONFIRMED:'待收款',PART_PAID:'部分收款',PAID:'已结清',VOID:'已作废'} as Record<string,string>)[status]||status
const orderStatusType=(status:string)=>({DRAFT:'info',CONFIRMED:'warning',PART_PAID:'warning',PAID:'success',VOID:'danger'} as Record<string,string>)[status]||'info'
const priceStatus=(status:string)=>status==='ENABLED'?'启用':'停用'
onMounted(load)
</script>
<template><section><div class="page-heading"><div><p>FINANCE</p><h1>财务管理</h1></div></div>
<el-tabs v-model="tab"><el-tab-pane label="收费单与收款" name="orders"><div class="tab-action-bar"><el-button v-if="auth.hasPermission('finance:charge:manage')" type="primary" @click="newOrder">新建收费单</el-button></div><div class="content-card"><el-table v-loading="loading" :data="orders"><el-table-column prop="orderNo" label="收费单号" width="170"/><el-table-column prop="customerName" label="委托单位" min-width="180"/><el-table-column prop="itemCodes" label="项目编码" min-width="140" show-overflow-tooltip/><el-table-column prop="itemNames" label="检测项目" min-width="190" show-overflow-tooltip/><el-table-column prop="sampleCount" label="样品数" width="80"/><el-table-column label="应收" width="120"><template #default="s">{{money(s.row.receivableAmount)}}</template></el-table-column><el-table-column label="实收" width="120"><template #default="s">{{money(s.row.paidAmount)}}</template></el-table-column><el-table-column label="状态" width="110"><template #default="s"><el-tag :type="orderStatusType(s.row.status) as any">{{orderStatus(s.row.status)}}</el-tag></template></el-table-column><el-table-column label="操作" width="390" fixed="right"><template #default="s"><div class="order-actions"><template v-if="s.row.status==='DRAFT'"><el-button class="order-action confirm-action" type="success" @click="confirm(s.row)">确认收费单</el-button><el-button class="order-action order-edit-action" type="primary" @click="editOrder(s.row)">修改</el-button><el-button class="order-action order-delete-action" type="danger" @click="removeOrder(s.row)">删除</el-button></template><template v-else-if="s.row.status==='CONFIRMED'"><el-button class="order-action payment-action" type="success" @click="openPay(s.row)">登记收款</el-button><el-button class="order-action return-action" type="warning" @click="returnOrder(s.row)">退回收费单</el-button></template><el-button v-else-if="s.row.status==='PART_PAID'" class="order-action payment-action" type="success" @click="openPay(s.row)">登记收款</el-button></div></template></el-table-column></el-table></div></el-tab-pane>
<el-tab-pane label="价目管理" name="prices"><div class="tab-action-bar"><el-button v-if="auth.hasPermission('finance:price:manage')" type="primary" @click="newPrice">新增价目</el-button></div><div class="content-card"><el-table :data="prices"><el-table-column prop="itemCode" label="项目编码"/><el-table-column prop="itemName" label="检测项目"/><el-table-column prop="testType" label="检测类型"/><el-table-column prop="unit" label="单位" width="70"/><el-table-column label="单价"><template #default="s">{{money(s.row.unitPrice)}}</template></el-table-column><el-table-column label="成本"><template #default="s">{{money(s.row.unitCost)}}</template></el-table-column><el-table-column prop="validFrom" label="生效日期"/><el-table-column label="状态" width="90"><template #default="s"><el-tag :type="s.row.status==='ENABLED'?'success':'info'">{{priceStatus(s.row.status)}}</el-tag></template></el-table-column><el-table-column label="编辑" width="210" fixed="right"><template #default="s"><div class="price-actions"><el-tooltip :content="s.row.referenced?'该检测项目已被收费单引用，不能修改':''" :disabled="!s.row.referenced" placement="top"><span class="action-tooltip"><el-button class="price-action price-edit-action" type="primary" :disabled="s.row.referenced" @click="editPrice(s.row)">修改</el-button></span></el-tooltip><el-tooltip :content="s.row.referenced?'该检测项目已被收费单引用，不能删除':''" :disabled="!s.row.referenced" placement="top"><span class="action-tooltip"><el-button class="price-action price-delete-action" type="danger" :disabled="s.row.referenced" @click="removePrice(s.row)">删除</el-button></span></el-tooltip></div></template></el-table-column></el-table></div></el-tab-pane></el-tabs>
<el-dialog v-model="priceVisible" :title="priceEditingId?'修改检测价目':'新增检测价目'" width="560px"><el-form label-width="90px"><el-form-item label="项目编码"><el-input v-model="price.itemCode"/></el-form-item><el-form-item label="项目名称"><el-input v-model="price.itemName"/></el-form-item><el-form-item label="检测类型"><el-input v-model="price.testType"/></el-form-item><el-form-item label="计价单位"><el-input v-model="price.unit"/></el-form-item><el-form-item label="收费单价"><el-input-number v-model="price.unitPrice" :min="0" :precision="2"/></el-form-item><el-form-item label="单位成本"><el-input-number v-model="price.unitCost" :min="0" :precision="2"/></el-form-item><el-form-item label="生效日期"><el-date-picker v-model="price.validFrom" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="失效日期"><el-date-picker v-model="price.validTo" clearable value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="状态"><el-radio-group v-model="price.status"><el-radio value="ENABLED">启用</el-radio><el-radio value="DISABLED">停用</el-radio></el-radio-group></el-form-item></el-form><template #footer><el-button @click="priceVisible=false">取消</el-button><el-button type="primary" @click="savePrice">保存</el-button></template></el-dialog>
<el-dialog v-model="orderVisible" :title="orderEditingId?'修改收费单':'新建收费单'" width="680px"><el-form label-width="90px"><el-form-item label="委托单位"><el-input v-model="order.customerName"/></el-form-item><el-form-item label="样品数量"><el-input-number v-model="order.sampleCount" :min="1"/></el-form-item><el-form-item label="检测项目"><div v-for="(i,n) in order.items" :key="n" style="display:flex;gap:10px;margin-bottom:8px;width:100%"><el-select v-model="i.priceItemId" filterable placeholder="请选择已启用的检测项目" style="flex:1"><el-option v-for="p in prices.filter(x=>x.status==='ENABLED')" :key="p.id" :label="`${p.itemCode} / ${p.itemName} / ${money(p.unitPrice)}`" :value="p.id"/></el-select><el-input-number v-model="i.quantity" :min="0.000001"/><el-button v-if="order.items.length>1" @click="order.items.splice(n,1)">删除</el-button></div><el-button link type="primary" @click="order.items.push({priceItemId:null,quantity:1})">+ 添加项目</el-button></el-form-item><el-form-item label="折扣金额"><el-input-number v-model="order.discountAmount" :min="0" :precision="2"/></el-form-item><el-form-item label="备注"><el-input v-model="order.remark" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="orderVisible=false">取消</el-button><el-button type="primary" @click="saveOrder">{{orderEditingId?'保存修改':'保存待确认'}}</el-button></template></el-dialog>
<el-dialog v-model="payVisible" title="登记收款" width="480px"><el-form label-width="90px"><el-form-item label="收款金额"><el-input-number v-model="payment.amount" :min="0.01" :precision="2"/></el-form-item><el-form-item label="收款方式"><el-select v-model="payment.method"><el-option label="银行转账" value="BANK"/><el-option label="现金" value="CASH"/><el-option label="其他" value="OTHER"/></el-select></el-form-item><el-form-item label="流水号"><el-input v-model="payment.referenceNo"/></el-form-item><el-form-item label="备注"><el-input v-model="payment.remark"/></el-form-item></el-form><template #footer><el-button @click="payVisible=false">取消</el-button><el-button type="primary" @click="savePay">确认收款</el-button></template></el-dialog></section></template>

<style scoped>
.tab-action-bar{display:flex;justify-content:flex-start;align-items:center;gap:10px;margin-bottom:12px}
.order-actions{display:flex;align-items:center;gap:4px}.order-actions :deep(.el-button+.el-button){margin-left:0}.order-action{min-width:82px;height:38px;padding:0 12px;border:0;border-radius:8px;font-size:14px;font-weight:800;letter-spacing:.5px;box-shadow:0 5px 14px rgba(45,92,190,.2);transition:transform .18s ease,box-shadow .18s ease}.order-action:hover{transform:translateY(-1px);box-shadow:0 8px 18px rgba(45,92,190,.28)}.confirm-action{min-width:108px;background:linear-gradient(110deg,#0fa36f,#25bd8a)}.order-edit-action{background:linear-gradient(110deg,#347df0,#5264dc)}.order-delete-action,.return-action{background:linear-gradient(110deg,#f05c68,#d9364e)}.return-action{min-width:108px}.payment-action{min-width:108px;background:linear-gradient(110deg,#f2a52b,#e67b18)}
.price-actions{display:flex;align-items:center;gap:10px}.action-tooltip{display:inline-flex}.price-action{min-width:78px;height:38px;padding:0 17px;border:0;border-radius:8px;font-size:14px;font-weight:800;letter-spacing:1px;box-shadow:0 4px 12px rgba(50,80,160,.2);transition:transform .18s ease,box-shadow .18s ease}.price-action:not(.is-disabled):hover{transform:translateY(-1px);box-shadow:0 7px 17px rgba(50,80,160,.3)}.price-edit-action{background:linear-gradient(110deg,#168bea,#515ee8)}.price-delete-action{background:linear-gradient(110deg,#f05c68,#d9364e)}.price-action.is-disabled{color:#9ca3af!important;background:#e5e7eb!important;border-color:#d1d5db!important;box-shadow:none!important;cursor:not-allowed}
.content-card :deep(.el-table__header th.el-table__cell),.content-card :deep(.el-table__header th.el-table__cell .cell){text-align:left}
</style>
